UPDATE STUDENT_DETAIL
   SET STUDENT_STATUS = #{studentStatus}
     , UPDATED_AT = SYSDATE
 WHERE STUDENT_NO = #{studentNo}

UPDATE MEMBER
   SET STATUS = 'ACTIVE'
	 , CLASS_NO = #{classNo}
	 , UPDATED_AT = SYSDATE
 WHERE USER_NO = #{userNo}

UPDATE BOARD_POST
   SET STATUS = #{status}
 WHERE POST_NO = #{postNo}

